// dsh-affection —— 版本更新检查（自动检测 npm 上有没有新版本）
//
// 只做「检测 + 报告」，不擅自替换自己的代码：DSH 没有热重载，
// 插件在运行中改自己的文件也只会下次重启才生效，风险不值得。
//
// 结果写到 <DSH_HOME>/plugin-updates.json，页面/日志都能读：
//   { "dsh-affection": { current, latest, updateAvailable, checkedAt, lastError? } }
//
// 频率：默认每 24 小时查一次；失败也记录时间，避免离线时每步重试。
import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';

/** '0.10.2' vs '0.9.9' → 1；相等 0；更小 -1。忽略预发布后缀。 */
export function compareVersions(a, b) {
  const parse = (v) =>
    String(v || '')
      .trim()
      .replace(/^v/i, '')
      .split('-')[0]
      .split('.')
      .map((x) => Number.parseInt(x, 10) || 0);
  const pa = parse(a);
  const pb = parse(b);
  const len = Math.max(pa.length, pb.length);
  for (let i = 0; i < len; i++) {
    const x = pa[i] || 0;
    const y = pb[i] || 0;
    if (x > y) return 1;
    if (x < y) return -1;
  }
  return 0;
}

export function createUpdateChecker({
  npmName,
  version,
  log,
  enabled = true,
  intervalHours = 24,
  registry = 'https://registry.npmjs.org',
}) {
  const dshHome = process.env.DSH_HOME || path.join(os.homedir(), '.dsh');
  const statePath = path.join(dshHome, 'plugin-updates.json');

  function readState() {
    try {
      const j = JSON.parse(fs.readFileSync(statePath, 'utf8'));
      return j && typeof j === 'object' ? j : {};
    } catch {
      return {};
    }
  }

  function writeState(state) {
    try {
      fs.mkdirSync(path.dirname(statePath), { recursive: true });
      const tmp = `${statePath}.tmp-${process.pid}`;
      fs.writeFileSync(tmp, JSON.stringify(state, null, 1), 'utf8');
      fs.renameSync(tmp, statePath);
    } catch {}
  }

  function record(partial) {
    const state = readState();
    state[npmName] = { ...(state[npmName] || {}), ...partial };
    writeState(state);
    return state[npmName];
  }

  async function check({ force = false } = {}) {
    if (!enabled) return null;
    const prev = readState()[npmName] || {};
    const now = Date.now();
    const interval = Math.max(1, Number(intervalHours) || 24) * 3600 * 1000;
    if (!force && prev.checkedAt && now - prev.checkedAt < interval) return prev;

    try {
      const res = await fetch(`${registry.replace(/\/+$/, '')}/${npmName.replace('/', '%2F')}/latest`, {
        headers: { accept: 'application/json' },
        signal: AbortSignal.timeout(8000),
      });
      if (!res.ok) throw new Error(`HTTP ${res.status}`);
      const j = await res.json();
      const latest = String(j?.version || '');
      if (!latest) throw new Error('响应里没有 version');
      const available = compareVersions(latest, version) > 0;
      const rec = record({
        current: version,
        latest,
        updateAvailable: available,
        checkedAt: now,
        lastError: '',
        updateCommand: available ? `dsh plugin --profile <你的profile> add ${npmName}@latest` : '',
      });
      if (available) {
        log?.(`发现新版本 ${latest}（当前 ${version}）：dsh plugin --profile <你的profile> add ${npmName}@latest`);
      }
      return rec;
    } catch (e) {
      const rec = record({
        current: version,
        checkedAt: now,
        lastError: String(e?.message ?? e),
      });
      log?.(`检查更新失败（不影响使用）：${rec.lastError}`);
      return rec;
    }
  }

  function get() {
    return readState()[npmName] || null;
  }

  return { check, get, npmName, version };
}
